<script lang="ts">
 import {onMount} from 'svelte';
 let {lang='en'}=$props<{lang?:'en'|'th'}>();
 const locales=['en','th','ja','zh-CN'];
 const text=lang==='th'?{back:'เครื่องมือผู้ขาย',title:'แค็ตตาล็อกสินค้า',search:'ค้นหาสินค้า',create:'สร้างสินค้า',save:'บันทึกสินค้าทั้งหมด',publish:'เผยแพร่',unpublish:'ยกเลิกเผยแพร่',archive:'เก็บถาวร',preview:'ดูตัวอย่าง',images:'รูปภาพ',options:'ตัวเลือก',skus:'SKU',add:'เพิ่ม',loading:'กำลังโหลด…',error:'บันทึกไม่สำเร็จ การแก้ไขยังอยู่'}:{back:'Seller tools',title:'Product catalog',search:'Search products',create:'Create product',save:'Save complete product',publish:'Publish',unpublish:'Unpublish',archive:'Archive',preview:'Preview',images:'Images',options:'Options',skus:'SKUs',add:'Add',loading:'Loading…',error:'Could not save. Your edits are preserved.'};
 let list=$state<any[]>([]),selected=$state<any>(null),query=$state(''),filter=$state(''),busy=$state(false),message=$state(''),lastSaved=$state(''),showPreview=$state(false),previewLocale=$state('en');
 let serialized=$derived(selected?JSON.stringify(selected):'');
 let dirty=$derived(Boolean(selected)&&serialized!==lastSaved);
 const labels=()=>Object.fromEntries(locales.map(locale=>[locale,'']));
 function friendlyError(code:string){const english:Record<string,string>={incomplete_translations:'Complete all four language sections before publishing.',invalid_catalog_images:'Add one primary HTTPS image and check every image URL.',invalid_catalog_options:'Check option codes, labels and values. Each value code must be unique.',invalid_catalog_skus:'Check every SKU, option combination, stock, price and weight.',invalid_catalog_product:'Check the product slug and required fields.',database_conflict:'This slug or SKU is already in use.',service_unavailable:'Seller tools are temporarily unavailable.'};const thai:Record<string,string>={incomplete_translations:'กรอกข้อมูลให้ครบทั้ง 4 ภาษาก่อนเผยแพร่',invalid_catalog_images:'เพิ่มรูป HTTPS และเลือกรูปหลักหนึ่งรูป',invalid_catalog_options:'ตรวจสอบรหัส ชื่อ และค่าตัวเลือก โดยรหัสค่าต้องไม่ซ้ำกัน',invalid_catalog_skus:'ตรวจสอบ SKU ตัวเลือก สต๊อก ราคา และน้ำหนัก',invalid_catalog_product:'ตรวจสอบ slug และข้อมูลสินค้าที่จำเป็น',database_conflict:'slug หรือ SKU นี้ถูกใช้แล้ว',service_unavailable:'เครื่องมือผู้ขายไม่พร้อมใช้งานชั่วคราว'};return(lang==='th'?thai:english)[code]??text.error;}
 async function loadList(){const r=await fetch(`/api/admin/catalog?q=${encodeURIComponent(query)}&lifecycle=${encodeURIComponent(filter)}`,{cache:'no-store'});if(!r.ok)throw Error();list=(await r.json()).products;}
 function canDiscard(){return !dirty||confirm(lang==='th'?'ละทิ้งการแก้ไขที่ยังไม่ได้บันทึกหรือไม่':'Discard unsaved changes?');}
 async function open(id:string,force=false){if(!force&&!canDiscard())return;busy=true;message='';try{const r=await fetch(`/api/admin/catalog/${id}`,{cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error);selected=data.product;lastSaved=JSON.stringify(selected);}catch(error){message=friendlyError(String((error as Error).message??''));}finally{busy=false;}}
 async function create(){if(!canDiscard())return;busy=true;try{const r=await fetch('/api/admin/catalog',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const data=await r.json();if(!r.ok)throw Error(data.error);await loadList();busy=false;await open(data.id,true);}catch(error){message=friendlyError(String((error as Error).message??''));busy=false;}}
 async function save(){if(!selected||busy)return false;busy=true;message='';try{const r=await fetch(`/api/admin/catalog/${selected.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(selected)});const data=await r.json();if(!r.ok)throw Error(data.error);selected=data.product;lastSaved=JSON.stringify(selected);message=lang==='th'?'บันทึกแล้ว':'Saved.';await loadList();return true;}catch(error){message=friendlyError(String((error as Error).message??''));return false;}finally{busy=false;}}
 async function lifecycle(value:string){if(!selected||busy||value==='archived'&&!confirm(lang==='th'?'เก็บสินค้านี้ถาวรหรือไม่':'Archive this product?'))return;if(dirty&&!(await save()))return;busy=true;try{const r=await fetch(`/api/admin/catalog/${selected.id}/lifecycle`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lifecycle:value})});const data=await r.json();if(!r.ok)throw Error(data.error);selected.lifecycle=value;if(value==='published')selected.slugLocked=true;lastSaved=JSON.stringify(selected);message=lang==='th'?'อัปเดตสถานะแล้ว':'Status updated.';await loadList();}catch(error){message=friendlyError(String((error as Error).message??''));}finally{busy=false;}}
 function addImage(){selected.images=[...selected.images,{url:'https://',alt:'',position:selected.images.length,primary:selected.images.length===0}];}
 function addGroup(){selected.optionGroups=[...selected.optionGroups,{code:'',position:selected.optionGroups.length,labels:labels(),values:[]}];}
 function addValue(group:any){group.values=[...group.values,{code:'',position:group.values.length,labels:labels()}];selected={...selected};}
 function addSku(){selected.skus=[...selected.skus,{sku:'',optionValueCodes:[],onHand:0,reserved:0,usd:null,jpy:null,thb:null,weightKg:null,salesMode:'checkout',lifecycle:'active'}];}
 function move<T>(items:T[],index:number,direction:-1|1){const target=index+direction;if(target<0||target>=items.length)return items;const next=[...items];[next[index],next[target]]=[next[target],next[index]];return next;}
 onMount(()=>{const beforeUnload=(event:BeforeUnloadEvent)=>{if(dirty){event.preventDefault();event.returnValue='';}};addEventListener('beforeunload',beforeUnload);loadList().catch(()=>message=text.error);return()=>removeEventListener('beforeunload',beforeUnload);});
</script>
<section class="mx-auto max-w-7xl space-y-6 px-4 py-10 md:px-6">
 <a class="btn" href={lang==='th'?'/th/admin':'/admin'}>← {text.back}</a><h1 class="font-serif text-4xl">{text.title}</h1>
 <div class="catalog-layout"><aside><div class="filters"><input class="input" type="search" placeholder={text.search} bind:value={query} onchange={()=>loadList()}/><select class="input" bind:value={filter} onchange={()=>loadList()}><option value="">All</option><option>draft</option><option>published</option><option>archived</option></select><button class="btn btn-primary" disabled={busy} onclick={create}>{text.create}</button></div>{#each list as product}<button class:selected={selected?.id===product.id} aria-current={selected?.id===product.id?'page':undefined} disabled={busy} class="product-row" onclick={()=>open(product.id)}><strong>{product.catalog_product_translations?.find((x:any)=>x.locale===lang)?.name||product.slug}</strong><small>{product.slug} · {product.lifecycle}</small></button>{/each}{#if !busy&&!list.length}<p>{lang==='th'?'ไม่พบสินค้า':'No products found.'}</p>{/if}</aside>
 {#if selected}<form inert={busy} onsubmit={event=>{event.preventDefault();void save();}}><div class="editor-head"><div><label>Slug<input class="input" bind:value={selected.slug} disabled={selected.slugLocked}/></label><label>Collection slug<input class="input" bind:value={selected.collectionSlug}/></label></div><span class="state">{selected.lifecycle}</span></div>
  <div class="translation-tabs">{#each locales as locale}{@const tr=selected.translations.find((x:any)=>x.locale===locale)}<fieldset><legend>{locale} {tr?.name&&tr?.shortDescription&&tr?.description?'✓':'!'}</legend>{#if tr}<label>Name<input class="input" maxlength="160" bind:value={tr.name}/></label><label>Badge<input class="input" maxlength="80" bind:value={tr.badge}/></label><label>Short description<textarea class="input" maxlength="500" bind:value={tr.shortDescription}></textarea></label><label>Description<textarea class="input tall" maxlength="10000" bind:value={tr.description}></textarea></label>{/if}</fieldset>{/each}</div>
  <section><h2>{text.images}</h2>{#each selected.images as image,i}<div class="row"><input class="input grow" type="text" inputmode="url" aria-label={`Image ${i+1} URL`} bind:value={image.url}/><input class="input grow" aria-label={`Image ${i+1} alternative text`} placeholder="Alt text" bind:value={image.alt}/><label><input type="radio" name="primary" checked={image.primary} onchange={()=>{selected.images.forEach((x:any)=>x.primary=x===image);selected={...selected};}}/> Primary</label><button type="button" class="btn" aria-label="Move image up" disabled={i===0} onclick={()=>selected.images=move(selected.images,i,-1)}>↑</button><button type="button" class="btn" aria-label="Move image down" disabled={i===selected.images.length-1} onclick={()=>selected.images=move(selected.images,i,1)}>↓</button><button type="button" class="btn" aria-label="Remove image" onclick={()=>selected.images=selected.images.filter((_:any,index:number)=>index!==i)}>×</button></div>{/each}<button type="button" class="btn" onclick={addImage}>{text.add} URL</button></section>
  <section><h2>{text.options}</h2>{#each selected.optionGroups as group,groupIndex}<div class="card"><div class="row"><label>Code<input class="input" bind:value={group.code}/></label><button type="button" class="btn" aria-label="Move option up" disabled={groupIndex===0} onclick={()=>selected.optionGroups=move(selected.optionGroups,groupIndex,-1)}>↑</button><button type="button" class="btn" aria-label="Move option down" disabled={groupIndex===selected.optionGroups.length-1} onclick={()=>selected.optionGroups=move(selected.optionGroups,groupIndex,1)}>↓</button><button type="button" class="btn danger" onclick={()=>selected.optionGroups=selected.optionGroups.filter((_:any,index:number)=>index!==groupIndex)}>Remove option</button></div><div class="labels">{#each locales as locale}<label>{locale}<input class="input" bind:value={group.labels[locale]}/></label>{/each}</div>{#each group.values as value,valueIndex}<div class="row"><input class="input" aria-label={`Option ${group.code||groupIndex+1} value code`} placeholder="Value code" bind:value={value.code}/>{#each locales as locale}<input class="input" aria-label={`${locale} label for ${value.code||`value ${valueIndex+1}`}`} placeholder={locale} bind:value={value.labels[locale]}/>{/each}<button type="button" class="btn" aria-label="Move value up" disabled={valueIndex===0} onclick={()=>{group.values=move(group.values,valueIndex,-1);selected={...selected};}}>↑</button><button type="button" class="btn" aria-label="Move value down" disabled={valueIndex===group.values.length-1} onclick={()=>{group.values=move(group.values,valueIndex,1);selected={...selected};}}>↓</button><button type="button" class="btn danger" onclick={()=>{group.values=group.values.filter((_:any,index:number)=>index!==valueIndex);selected={...selected};}}>×</button></div>{/each}<button type="button" class="btn" onclick={()=>addValue(group)}>{text.add} value</button></div>{/each}<button type="button" class="btn" onclick={addGroup}>{text.add} option</button></section>
  <section><h2>{text.skus}</h2><div class="table-wrap"><table><thead><tr><th>SKU</th><th>Options</th><th>Stock / reserved</th><th>USD / JPY / THB</th><th>kg</th><th>Mode</th><th>State</th></tr></thead><tbody>{#each selected.skus as sku}<tr><td><input class="input" aria-label="SKU code" bind:value={sku.sku} disabled={Boolean(sku.id)}/></td><td><div class="sku-option-selects">{#each selected.optionGroups as group}<label><span>{group.labels[lang]||group.code}</span><select class="input" value={sku.optionValueCodes.find((code:string)=>group.values.some((value:any)=>value.code===code))??''} onchange={event=>{const other=sku.optionValueCodes.filter((code:string)=>!group.values.some((value:any)=>value.code===code));sku.optionValueCodes=[...other,event.currentTarget.value].filter(Boolean);selected={...selected};}}><option value="">Choose…</option>{#each group.values as value}<option value={value.code}>{value.labels[lang]||value.code}</option>{/each}</select></label>{/each}</div></td><td><input class="input small" aria-label="Stock on hand" type="number" min="0" step="1" bind:value={sku.onHand}/> / {sku.reserved}</td><td><input class="input tiny" aria-label="Price in USD" type="number" min="0" step="0.01" bind:value={sku.usd}/> <input class="input tiny" aria-label="Price in JPY" type="number" min="0" step="1" bind:value={sku.jpy}/> <input class="input tiny" aria-label="Price in THB" type="number" min="0" step="0.01" bind:value={sku.thb}/></td><td><input class="input small" aria-label="Gross weight in kilograms" type="number" min="0" step="0.001" bind:value={sku.weightKg}/></td><td><select class="input" aria-label="Sales mode" bind:value={sku.salesMode}><option value="checkout">checkout</option><option value="reservation_only">reservation only</option></select></td><td><select class="input" aria-label="SKU state" bind:value={sku.lifecycle}><option>active</option><option>archived</option></select></td></tr>{/each}</tbody></table></div><button type="button" class="btn" onclick={addSku}>{text.add} SKU</button><p class="hint">{lang==='th'?'รหัส SKU ที่บันทึกแล้วเปลี่ยนชื่อไม่ได้ หากเลิกขายให้เปลี่ยนสถานะเป็น archived':'Saved SKU codes cannot be renamed. Set a discontinued SKU to archived.'}</p></section>
  <div class="actions"><button class="btn btn-primary" disabled={busy||!dirty}>{busy?text.loading:text.save}</button>{#if dirty}<span class="unsaved">{lang==='th'?'มีการแก้ไขที่ยังไม่ได้บันทึก':'Unsaved changes'}</span>{/if}{#if selected.lifecycle!=='published'}<button type="button" class="btn" disabled={busy} onclick={()=>lifecycle('published')}>{text.publish}</button>{:else}<button type="button" class="btn" disabled={busy} onclick={()=>lifecycle('draft')}>{text.unpublish}</button>{/if}<button type="button" class="btn danger" disabled={busy} onclick={()=>lifecycle('archived')}>{text.archive}</button><button type="button" class="btn" onclick={()=>showPreview=!showPreview}>{text.preview}</button>{#if selected.lifecycle==='published'}<a class="btn" target="_blank" href={`${lang==='en'?'':'/'+lang}/product/${selected.slug}`}>Public page ↗</a>{/if}</div>
  {#if showPreview}{@const preview=selected.translations.find((row:any)=>row.locale===previewLocale)}<section class="draft-preview" aria-label="Product preview"><div class="row"><h2>{text.preview}</h2><select class="input" bind:value={previewLocale}>{#each locales as locale}<option value={locale}>{locale}</option>{/each}</select></div>{#if selected.images[0]}<img src={(selected.images.find((image:any)=>image.primary)??selected.images[0]).url} alt={(selected.images.find((image:any)=>image.primary)??selected.images[0]).alt}/>{/if}<p class="state">{preview?.badge}</p><h3>{preview?.name||selected.slug}</h3><p>{preview?.shortDescription}</p><p>{preview?.description}</p></section>{/if}
 </form>{:else}<p>{busy?text.loading:''}</p>{/if}</div><p role="status">{message}</p>
</section>
<style>.catalog-layout{display:grid;grid-template-columns:18rem minmax(0,1fr);gap:1.5rem}aside,form{border:1px solid #ffffff22;border-radius:1rem;padding:1rem;background:#1115}.filters{display:grid;gap:.6rem;margin-bottom:1rem}.product-row{display:grid;width:100%;padding:.8rem;text-align:left;border-top:1px solid #ffffff18}.product-row.selected{background:#ffffff12}.product-row small{color:#aaa}.editor-head,.row,.actions{display:flex;gap:.7rem;align-items:end;flex-wrap:wrap}.editor-head{justify-content:space-between}.state{padding:.35rem .7rem;border:1px solid #ffffff33;border-radius:99px}.translation-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;margin-block:1.5rem}.translation-tabs fieldset,.card,form>section{border:1px solid #ffffff20;border-radius:.7rem;padding:1rem}.translation-tabs label,.card label{display:grid;gap:.25rem;margin-top:.55rem}.tall{min-height:8rem}.grow{flex:1 1 15rem}.labels{display:grid;grid-template-columns:repeat(4,1fr);gap:.5rem}.table-wrap{overflow:auto}table{min-width:1050px;width:100%;border-collapse:collapse}th,td{padding:.5rem;border-bottom:1px solid #ffffff18;text-align:left}.small{width:5rem}.tiny{width:5.5rem}.danger{border-color:#a55;color:#fcc}.hint,.unsaved{color:#e7cf98;font-size:.9rem}.draft-preview img{display:block;max-height:24rem;margin-block:1rem;object-fit:contain}.draft-preview h3{font-family:var(--font-serif);font-size:2rem}.actions{position:sticky;bottom:0;padding:1rem;background:#101313eF;margin-top:1rem}@media(max-width:850px){.catalog-layout{grid-template-columns:1fr}.translation-tabs{grid-template-columns:1fr}.labels{grid-template-columns:1fr 1fr}}.sku-option-selects{display:grid;gap:.45rem}.sku-option-selects label{display:grid;gap:.25rem;font-size:.85rem}.product-row[aria-current=page]{outline:2px solid #d8ba78;outline-offset:-2px}</style>
